/**
 * ACROVIX AI Assistant — Local Knowledge-Base Response Engine
 *
 * 100% free, runs entirely in the browser. No external AI API, no API key,
 * and no server round-trip required. Answers are generated by matching the
 * visitor's message against ACROVIX's own site content (services, industries,
 * products, portfolio, and company info), so responses always stay accurate
 * and in sync with the rest of the website.
 */

import { COMPANY_INFO } from '../../data/company';
import { SERVICES_DATA } from '../../data/services';
import { INDUSTRIES_DATA } from '../../data/industries';
import { PRODUCTS_DATA } from '../../data/products';
import { PORTFOLIO_DATA } from '../../data/portfolio';

export const INITIAL_WELCOME_MESSAGE = {
  id: 'welcome_1',
  sender: 'ai',
  text: `Hello! Welcome to ACROVIX 👋 I'm the ACROVIX Assistant. I can help you explore our services, products, industries we serve, or connect you with our team. What would you like to know?`,
  timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
  showQuickActions: true
};

export const QUICK_ACTIONS = [
  { id: 'qa_services', label: 'Explore Services', action: 'services', path: '/services' },
  { id: 'qa_products', label: 'Explore Products', action: 'products', path: '/products' },
  { id: 'qa_industries', label: 'Industries We Serve', action: 'industries', path: '/industries' },
  { id: 'qa_consultation', label: 'Request Consultation', action: 'consultation', path: '/enquiry' },
  { id: 'qa_contact', label: 'Contact Us', action: 'contact', path: '/contact' }
];

const now = () => new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

const reply = (text, link = null) => ({
  id: `ai_${Date.now()}_${Math.floor(Math.random() * 1000)}`,
  sender: 'ai',
  text,
  link,
  timestamp: now()
});

/** True if the query contains at least one of the given keywords/phrases. */
function includesAny(query, keywords) {
  return keywords.some((kw) => query.includes(kw));
}

/**
 * Demo AI Response Engine
 * Evaluates the visitor's message against ACROVIX's own content and
 * returns the most relevant answer, with an optional "learn more" link.
 *
 * @param {string} userMessage - Text typed by the user
 * @returns {Object} Response message object rendered by <AIMessage />
 */
export function getAIResponse(userMessage) {
  const query = userMessage.toLowerCase().trim();

  if (!query) {
    return reply("Could you tell me a bit more about what you're looking for? I can help with services, products, industries, or connecting you with our team.");
  }

  // ---------- 1. Greetings ----------
  if (includesAny(query, ['hello', 'hi ', 'hi', 'hey', 'namaste', 'good morning', 'good afternoon', 'good evening', 'greetings'])) {
    return reply("Hello there! 👋 How can ACROVIX assist your organization today? Feel free to ask about our services, products, industries, or request a technical consultation.");
  }

  // ---------- 2. Thanks ----------
  if (includesAny(query, ['thank', 'thanks', 'appreciate', 'thankyou', 'thank you'])) {
    return reply("You're most welcome! If anything else comes to mind — services, pricing, or a consultation — I'm right here. 😊");
  }

  // ---------- 3. Goodbye ----------
  if (includesAny(query, ['bye', 'goodbye', 'see you', 'exit', 'close chat'])) {
    return reply("Thanks for stopping by ACROVIX! Have a great day, and feel free to reopen this chat anytime you have a question.");
  }

  // ---------- 4. Bot identity ----------
  if (includesAny(query, ['are you human', 'are you a bot', 'are you ai', 'are you real', 'who are you', 'what are you'])) {
    return reply("I'm the ACROVIX Assistant — a virtual guide built to help you quickly find the right service, product, or contact at ACROVIX. For deeply technical or commercial discussions, I'll always connect you with our human team.");
  }

  // ---------- 5. Pricing / cost / quote ----------
  if (includesAny(query, ['price', 'pricing', 'cost', 'how much', 'charges', 'fees', 'budget', 'quote', 'quotation'])) {
    return reply(
      "ACROVIX solutions are tailored to each organization's scale, infrastructure, and compliance needs, so pricing is customized rather than one-size-fits-all. Share your requirement through our enquiry form and our solution architects will get back to you with a detailed quote.",
      { label: 'Request a Quote', path: '/enquiry' }
    );
  }

  // ---------- 6. Careers / jobs ----------
  if (includesAny(query, ['career', 'careers', 'job', 'jobs', 'hiring', 'vacancy', 'work with acrovix', 'internship'])) {
    return reply(
      `We don't have a dedicated careers portal live just yet. If you'd like to explore opportunities with ${COMPANY_INFO.shortName}, please write to us directly and our team will get back to you.`,
      { label: 'Email Us', path: '/contact' }
    );
  }

  // ---------- 7. Location / address / office ----------
  if (includesAny(query, ['location', 'address', 'where are you', 'office', 'headquarters', 'based in', 'city'])) {
    return reply(
      "For detailed location and office information, please reach out via our Contact page — our team will be happy to assist and, where relevant, arrange a visit or virtual meeting.",
      { label: 'Go to Contact Page', path: '/contact' }
    );
  }

  // ---------- 8. XDA ----------
  if (includesAny(query, ['xda', 'xcel data armour', 'diagnostics', 'telemetry'])) {
    return reply(
      "ACROVIX XDA (Xcel Data Armour) is our unified platform for data security, protection, and observability — offering centralized visibility, threat telemetry, PII masking, and continuous compliance assurance for enterprise leadership.",
      { label: 'Discover ACROVIX XDA', path: '/xda' }
    );
  }

  // ---------- 9. Specific service match ----------
  const matchedService = SERVICES_DATA.find((service) => {
    const haystack = [service.title, service.category, ...(service.capabilities || [])]
      .join(' ')
      .toLowerCase();
    return service.title.toLowerCase().split(' ').some((word) => word.length > 3 && query.includes(word))
      || includesAny(query, haystack.split(',').map((s) => s.trim().toLowerCase()).filter(Boolean))
      || (service.slug === 'cybersecurity-observability' && includesAny(query, ['cybersecurity', 'security', 'ransomware', 'vapt', 'data protection', 'observability', 'compliance', 'threat']))
      || (service.slug === 'enterprise-it' && includesAny(query, ['enterprise it', 'cloud', 'devops', 'infrastructure', 'system integration', 'api management', 'database migration']));
  });
  if (matchedService) {
    return reply(
      `${matchedService.title}: ${matchedService.shortDescription}`,
      { label: `Explore ${matchedService.title}`, path: `/services/${matchedService.slug}` }
    );
  }

  // ---------- 10. General services ----------
  if (includesAny(query, ['service', 'solution', 'what do you do', 'what does acrovix do', 'help with', 'offer'])) {
    const titles = SERVICES_DATA.map((s) => s.title).join(' and ');
    return reply(
      `ACROVIX delivers ${titles.toLowerCase()} — covering cloud & DevOps, system integration, API management, infrastructure deployment, and 24/7 managed services.`,
      { label: 'View All Services', path: '/services' }
    );
  }

  // ---------- 11. Specific industry match ----------
  const matchedIndustry = INDUSTRIES_DATA.find((ind) => query.includes(ind.title.toLowerCase()) || query.includes(ind.slug.replace(/-/g, ' ')));
  if (matchedIndustry) {
    return reply(
      `For ${matchedIndustry.title}: ${matchedIndustry.shortDescription}`,
      { label: `See ${matchedIndustry.title} Solutions`, path: `/industries/${matchedIndustry.slug}` }
    );
  }

  // ---------- 12. General industries ----------
  if (includesAny(query, ['industry', 'industries', 'sector', 'domain', 'vertical'])) {
    const list = INDUSTRIES_DATA.slice(0, 5).map((i) => i.title).join(', ');
    return reply(
      `ACROVIX serves a wide range of industries including ${list}, and more — each with tailored technology and security solutions.`,
      { label: 'View All Industries', path: '/industries' }
    );
  }

  // ---------- 13. Specific product / vendor match ----------
  const matchedProduct = PRODUCTS_DATA.find((p) => query.includes(p.vendor.toLowerCase()) || query.includes(p.name.toLowerCase()));
  if (matchedProduct) {
    return reply(
      `${matchedProduct.name}: ${matchedProduct.shortDescription}`,
      { label: 'Browse Product Portfolio', path: '/products' }
    );
  }

  // ---------- 14. General products ----------
  if (includesAny(query, ['product', 'vendor', 'storage', 'backup', 'vdi', 'firewall', 'endpoint', 'antivirus', 'encryption', 'identity', 'iam'])) {
    const vendors = [...new Set(PRODUCTS_DATA.map((p) => p.vendor))].slice(0, 8).join(', ');
    return reply(
      `ACROVIX partners with industry-leading vendors including ${vendors}, and more — spanning virtualization, cloud storage, data protection, endpoint security, and identity management.`,
      { label: 'Browse Product Portfolio', path: '/products' }
    );
  }

  // ---------- 15. Portfolio / case studies ----------
  if (includesAny(query, ['portfolio', 'case study', 'case studies', 'past work', 'projects', 'clients', 'experience', 'track record'])) {
    const list = PORTFOLIO_DATA.map((p) => p.title).join(' | ');
    return reply(
      `Here's a glimpse of our work: ${list}. You can see the full breakdown — client requirement, solution, and measurable outcomes — on our Portfolio page.`,
      { label: 'View Case Studies', path: '/portfolio' }
    );
  }

  // ---------- 16. About / company ----------
  if (includesAny(query, ['about', 'who is acrovix', 'about acrovix', 'company', 'vision', 'mission', 'tagline', 'sync scale succeed'])) {
    return reply(
      `${COMPANY_INFO.name} — "${COMPANY_INFO.tagline}". ${COMPANY_INFO.description}`,
      { label: 'Learn More About Us', path: '/about' }
    );
  }

  // ---------- 17. Consultation / project enquiry ----------
  if (includesAny(query, ['project', 'consultation', 'consult', 'discuss', 'requirement', 'enquiry', 'inquiry', 'get started', 'talk to someone', 'demo'])) {
    return reply(
      "Sure! I can help you get started. Please share your requirement and our team will review it — you can also request a direct consultation with our solution architects.",
      { label: 'Request a Consultation', path: '/enquiry' }
    );
  }

  // ---------- 18. Contact ----------
  if (includesAny(query, ['contact', 'email', 'phone', 'reach', 'support', 'call', 'number', 'talk to'])) {
    return reply(
      `You can reach our team at ${COMPANY_INFO.contact.email} or ${COMPANY_INFO.contact.phone}, or submit your query directly on our Contact page.`,
      { label: 'Go to Contact Page', path: '/contact' }
    );
  }

  // ---------- 19. Fallback ----------
  return reply(
    "Thanks for reaching out! I might not have caught that exactly — could you tell me a bit more? You can ask me about our services, products, industries we serve, or request a consultation with our team.",
    { label: 'Talk to Our Team', path: '/enquiry' }
  );
}
